mapper.select:
select m.id, m.parent_id, m.menu_type, m.name, m.path, m.component, m.title, m.icon, m.sort, m.is_hide, m.is_hide_tab, m.keep_alive, m.is_full_page, m.is_first_level, m.fixed_tab, m.link, m.is_iframe, m.active_path, m.auth_mark, m.is_enabled, m.create_time, m.update_time from blog_menu m where m.deleted_at = 0
and (m.title like concat('%', #{keyword}, '%') or m.path like concat('%', #{keyword}, '%') or m.auth_mark like concat('%', #{keyword}, '%'))
and m.menu_type = #{menuType}
and m.is_enabled = #{isEnabled}
order by m.sort, m.id

select m.id, m.parent_id, m.menu_type, m.name, m.path, m.component, m.title, m.icon, m.sort, m.is_hide, m.is_hide_tab, m.keep_alive, m.is_full_page, m.is_first_level, m.fixed_tab, m.link, m.is_iframe, m.active_path, m.auth_mark from blog_menu m where m.deleted_at = 0 and m.is_enabled = 1 and m.id in
#{id}
order by m.sort, m.id

select m.id, m.parent_id, m.menu_type, m.name, m.path, m.component, m.title, m.icon, m.sort, m.is_hide, m.is_hide_tab, m.keep_alive, m.is_full_page, m.is_first_level, m.fixed_tab, m.link, m.is_iframe, m.active_path, m.auth_mark, m.is_enabled, m.create_time, m.update_time from blog_menu m where m.deleted_at = 0 and m.id in
#{id}
order by m.sort, m.id

select count(*)
from blog_menu
where deleted_at = 0
  and parent_id = #{parentId}
  and path = #{path}

  and id != #{excludeId}

select count(*)
from blog_menu
where deleted_at = 0
  and parent_id = #{parentId}
  and auth_mark = #{authMark}

  and id != #{excludeId}

select count(*)
from blog_menu
where deleted_at = 0
  and name = #{name}

  and id != #{excludeId}

mapper.update:
update blog_menu
set deleted_at = #{deletedAt}
where deleted_at = 0
  and id = #{id}
